package com.example.resume_matching_analytics.Analytics;

import jakarta.persistence.*;

import java.time.OffsetDateTime;


// create table analytics (timestamp timestamptz default current_timestamp not null, data jsonb not null, type text not null, username text not null, id bigint generated by default as identity primary key);
// create unique index on analytics ((data->>'session_id'), username, type);
@Entity
@Table
public class Analytics {
    //    private Long id;
    @Column(columnDefinition = "TEXT")
    private String type;

    @Id
    @Column(name = "timestamp", nullable = false, updatable = false, columnDefinition = "timestamptz NOT NULL")
    private OffsetDateTime timestamp;

    @Column(columnDefinition = "TEXT")
    private String data;

    @Column(columnDefinition = "TEXT")
    private String username;

    public Analytics() {
    }


    public Analytics(String type) {
        this.type = type;
    }

//    public Long getId() {
//        return id;
//    }

    public String getType() {
        return type;
    }

    public void setType(String type) {
        this.type = type;
    }

    public OffsetDateTime getTime() {
        return timestamp;
    }

    @Override
    public String toString() {
        return "Analytics{" +
                ", type='" + type + '\'' +
                '}';
    }

    public String getData() {
        return data;
    }

    public void setData(String data) {
        this.data = data;
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }
}

